// ---- Complete implementation with tests ----

use std::fs;
use std::path::{Path, PathBuf};
use std::collections::HashMap;
use std::io;

// ---- Error types ----
#[derive(Debug)]
enum OrganizerError {
    Io(io::Error),
    InvalidPath(String),
}

impl From<io::Error> for OrganizerError {
    fn from(err: io::Error) -> Self {
        OrganizerError::Io(err)
    }
}

type Result<T> = std::result::Result<T, OrganizerError>;

// ---- Main organizer ----
pub struct FileOrganizer {
    source_dir: PathBuf,
    verbose: bool,
    dry_run: bool,
}

impl FileOrganizer {
    pub fn new(source_dir: PathBuf, verbose: bool, dry_run: bool) -> Self {
        FileOrganizer { source_dir, verbose, dry_run }
    }

    pub fn run(&self) -> Result<()> {
        if !self.source_dir.exists() {
            return Err(OrganizerError::InvalidPath(
                format!("Directory does not exist: {:?}", self.source_dir)
            ));
        }

        let files = self.scan_directory()?;
        let groups = self.group_by_extension(&files);

        if self.verbose {
            self.display_groups(&groups);
        }

        if !self.dry_run {
            self.organize_files(&groups)?;
        }

        Ok(())
    }

    fn scan_directory(&self) -> Result<Vec<PathBuf>> {
        let mut files = Vec::new();
        for entry in fs::read_dir(&self.source_dir)? {
            let entry = entry?;
            let path = entry.path();
            if path.is_file() && !self.is_hidden(&path) {
                files.push(path);
            }
        }
        Ok(files)
    }

    fn is_hidden(&self, path: &Path) -> bool {
        path.file_name()
            .and_then(|name| name.to_str())
            .map(|s| s.starts_with('.'))
            .unwrap_or(false)
    }

    fn group_by_extension(&self, files: &[PathBuf]) -> HashMap<String, Vec<PathBuf>> {
        let mut groups: HashMap<String, Vec<PathBuf>> = HashMap::new();

        for file in files {
            let ext = file.extension()
                .and_then(|e| e.to_str())
                .unwrap_or("no_extension")
                .to_string();

            groups.entry(ext).or_insert_with(Vec::new).push(file.clone());
        }

        groups
    }

    fn display_groups(&self, groups: &HashMap<String, Vec<PathBuf>>) {
        println!("\n=== File Groups ===");
        let mut sorted: Vec<(&String, &Vec<PathBuf>)> = groups.iter().collect();
        sorted.sort_by(|a, b| a.0.cmp(b.0));

        for (ext, files) in sorted {
            println!("  .{}: {} files", ext, files.len());
        }
    }

    fn organize_files(&self, groups: &HashMap<String, Vec<PathBuf>>) -> Result<()> {
        for (ext, files) in groups {
            let dir = self.source_dir.join(ext);

            if !dir.exists() {
                fs::create_dir(&dir)?;
                if self.verbose {
                    println!("Created directory: {:?}", dir);
                }
            }

            for file in files {
                let dest = dir.join(file.file_name().unwrap());
                fs::rename(file, &dest)?;
                if self.verbose {
                    println!("Moved: {:?}", file.file_name().unwrap());
                }
            }
        }
        Ok(())
    }
}

// ---- Tests ----
#[cfg(test)]
mod tests {
    use super::*;
    use std::env;
    use std::fs::File;

    fn create_test_dir() -> PathBuf {
        let temp_dir = env::temp_dir().join("file_organizer_test");
        let _ = fs::remove_dir_all(&temp_dir);
        fs::create_dir_all(&temp_dir).unwrap();

        // Create some test files
        File::create(temp_dir.join("test1.txt")).unwrap();
        File::create(temp_dir.join("test2.txt")).unwrap();
        File::create(temp_dir.join("test.rs")).unwrap();
        File::create(temp_dir.join(".hidden")).unwrap();

        temp_dir
    }

    #[test]
    fn test_scan_directory() {
        let temp_dir = create_test_dir();
        let organizer = FileOrganizer::new(temp_dir.clone(), false, true);
        let files = organizer.scan_directory().unwrap();

        // Should find 3 files (not .hidden)
        assert_eq!(files.len(), 3);

        // Should include .txt and .rs files
        let has_txt = files.iter().any(|f| f.extension().unwrap() == "txt");
        let has_rs = files.iter().any(|f| f.extension().unwrap() == "rs");
        assert!(has_txt);
        assert!(has_rs);
    }

    #[test]
    fn test_group_by_extension() {
        let files = vec![
            PathBuf::from("file1.txt"),
            PathBuf::from("file2.txt"),
            PathBuf::from("file3.rs"),
        ];

        let organizer = FileOrganizer::new(PathBuf::from("."), false, true);
        let groups = organizer.group_by_extension(&files);

        assert_eq!(groups.len(), 2);
        assert_eq!(groups.get("txt").unwrap().len(), 2);
        assert_eq!(groups.get("rs").unwrap().len(), 1);
    }

    #[test]
    fn test_is_hidden() {
        let organizer = FileOrganizer::new(PathBuf::from("."), false, true);
        assert!(organizer.is_hidden(Path::new(".hidden")));
        assert!(!organizer.is_hidden(Path::new("visible")));
    }

    #[test]
    fn test_invalid_directory() {
        let organizer = FileOrganizer::new(
            PathBuf::from("/nonexistent/dir"),
            false,
            true,
        );

        let result = organizer.run();
        assert!(result.is_err());
    }
}

fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let source_dir = args.get(1)
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));

    let verbose = args.contains(&"-v".to_string()) || args.contains(&"--verbose".to_string());
    let dry_run = args.contains(&"-n".to_string()) || args.contains(&"--dry-run".to_string());

    let organizer = FileOrganizer::new(source_dir, verbose, dry_run);
    organizer.run()
}

